class Solution {
public:
    bool isPrefixString(string s, vector<string>& words) {
        int i=0;
        for(const string& w:words){
            for(char c:w){if(i==(int)s.size()||s[i]!=c)return false;++i;}
            if(i==(int)s.size())return true;
        }
        return false;
    }
};
